import { Image } from '@chakra-ui/react'
import type { ImageProps } from '@chakra-ui/react'

import { MyBasicCarousel } from '~/ui/parts/MyCarousel'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'


type Prop = ImageProps & {
  imageList: string[];
  imageWidth?: string;
}
export function ImageListView(prop: Prop) {
  const { imageList, imageWidth = '100%', ...otherProp } = prop;
  
  return (
    <MyBasicCarousel
      slideList={imageList.map((image) => (
        <Image src={image} css={styles.image} loading='lazy' {...otherProp} />
      ))}
      w={imageWidth}
    />
  )
}

const styles = {
  image: css`
    object-fit: contain;
    width: 100%;
    aspect-ratio: 16 / 9;
    background-color: black;
  `
}
